<script setup lang="ts">
import { reactive, ref, computed, watch, onBeforeUnmount } from 'vue';
import AdminDialog from '../../shared/ui/AdminDialog.vue';
import RemoteSelect from './RemoteSelect.vue';
import { useDirty, errorText, type Option } from './shared';
export interface Field { key:string;label:string;excludeId?:string;type?:string;required?:boolean;options?:Option[];endpoint?:string|((values:Record<string,string>)=>string);hint?:string;max?:number;min?:number;initial?:string; }
const props=defineProps<{title:string;description?:string;fields:Field[];initial?:Record<string,string>;submitLabel?:string;onRefresh?:()=>Promise<string>;onSubmit:(values:Record<string,string>)=>Promise<void>}>();
const emit=defineEmits<{close:[]}>();
const values=reactive<Record<string,string>>({}),busy=ref(false),error=ref(''),discard=ref(false);let original='';
watch(()=>props.fields,fields=>{for(const f of fields)if(!(f.key in values))values[f.key]=props.initial?.[f.key]??f.initial??'';if(!original)original=JSON.stringify(values);},{immediate:true});
const dirty=computed(()=>JSON.stringify(values)!==original);
const refreshed=ref('');
async function refresh(){if(!props.onRefresh)return;busy.value=true;try{refreshed.value=await props.onRefresh();error.value='';}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
useDirty(()=>dirty.value,()=>busy.value);
function close(){if(busy.value)return;if(dirty.value){discard.value=true;return;}emit('close');}
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{await props.onSubmit({...values});original=JSON.stringify(values);for(const f of props.fields)if(f.type==='password')values[f.key]='';emit('close');}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
const guard=(e:BeforeUnloadEvent)=>{if(dirty.value||busy.value){e.preventDefault();e.returnValue='';}};
window.addEventListener('beforeunload',guard);onBeforeUnmount(()=>{window.removeEventListener('beforeunload',guard);Object.keys(values).forEach(k=>values[k]='');});
</script>
<template><AdminDialog open :title="title" :description="description" title-id="task-title" @close="close"><form class="contents" @submit.prevent="submit"><div class="admin-dialog-body space-y-4"><div v-if="error" class="admin-notice admin-notice-error" role="alert">{{error}}<button v-if="onRefresh" class="mt-2 block underline" type="button" :disabled="busy" @click="refresh">读取最新事实并保留当前输入</button></div><p v-if="refreshed" class="admin-notice admin-notice-info">{{refreshed}}。请对照当前输入，核对后再提交。</p><div v-if="discard" class="admin-notice admin-notice-warning flex flex-wrap items-center gap-2">丢弃未保存的输入？<button type="button" class="btn-secondary" @click="emit('close')">丢弃</button><button type="button" class="btn-ghost" @click="discard=false">继续填写</button></div><fieldset :disabled="busy" class="grid gap-3 sm:grid-cols-2"><label v-for="f in fields" :key="f.key" :class="f.type==='textarea'?'sm:col-span-2':''"><span class="admin-form-label">{{f.label}} <b v-if="f.required">*</b></span><RemoteSelect v-if="f.endpoint" v-model="values[f.key]" :endpoint="typeof f.endpoint==='function'?f.endpoint(values):f.endpoint" :label="f.label" :exclude-id="f.excludeId" clear-on-endpoint-change :required="f.required"/><select v-else-if="f.options" v-model="values[f.key]" class="admin-field" :required="f.required"><option value="">请选择</option><option v-for="o in f.options" :key="o.value" :value="o.value">{{o.label}}</option></select><textarea v-else-if="f.type==='textarea'" v-model="values[f.key]" class="admin-field" rows="3" :required="f.required" :maxlength="f.max??2000"/><input v-else v-model="values[f.key]" class="admin-field" :type="f.type??'text'" :required="f.required" :maxlength="f.max??200" :min="f.min" :max="f.type==='number'?f.max:undefined" :step="f.type==='number'?'any':undefined" :autocomplete="f.type==='password'?'new-password':'off'"><span v-if="f.hint" class="mt-1 block text-xs leading-5 text-gray-500">{{f.hint}}</span></label></fieldset></div><footer class="admin-dialog-footer"><button type="button" class="btn-secondary" :disabled="busy" @click="close">取消</button><button class="btn-primary" :disabled="busy">{{busy?'提交中…':submitLabel??'保存'}}</button></footer></form></AdminDialog></template>
